// packages/react/src/components/Dropdown/stories/ReadOnly.stories.jsx
import React, { useState } from 'react';
import { Dropdown } from '../Dropdown';

const items = [
  { id: 'option-0', text: 'Option 0' },
  { id: 'option-1', text: 'Option 1' },
  { id: 'option-2', text: 'Option 2' },
];

export default {
  title: 'Components/Dropdown/ReadOnly',
  component: Dropdown,
  argTypes: {
    readOnly: { control: 'boolean' },
    invalid: { control: 'boolean' },
    invalidText: { control: 'text' },
  },
};

const Template = (args) => {
  const [selected, setSelected] = useState(items[0]);
  return (
    <div style={{ width: '280px' }}>
      <Dropdown
        {...args}
        id="read-only-dropdown"
        items={items}
        itemToString={(item) => (item ? item.text : '')}
        selectedItem={selected}
        onChange={({ selectedItem }) => setSelected(selectedItem)}
        label="Select an option"
        placeholder="Choose an option..."
      />
    </div>
  );
};

export const Default = Template.bind({});
Default.args = {
  readOnly: true,
};

export const WithError = Template.bind({});
WithError.args = {
  readOnly: true,
  invalid: true,
  invalidText: 'Error message here',
};
